arguments.command:
cd /tmp/sv-c8a9207f17fd41dca8a2712b8a08c504 && aarch64-linux-gnu-nm -S libmonosgen-2.0.so.debug 2>/dev/null | awk -v t1="0x2f4b20" -v t2="0x2f4c84" -v t3="0x2c1a40" '
{
  addr=strtonum("0x"$1)
  if (NF>=4) { size=strtonum("0x"$2); sym=$4 }
  else if (NF>=3) { size=0; sym=$3 }
  else next
  if ($2 ~ /^[tTwW]$/ || $3 ~ /^[tTwW]$/) {
    # function symbol
    if (NF>=4) { type=$3 } else { type=$2 }
  }
}
type ~ /[tTwW]/ {
  if (addr <= strtonum(t1) && addr+size > strtonum(t1)) printf "%s contains %s (offset +0x%x)\n", sym, t1, strtonum(t1)-addr
  if (addr <= strtonum(t2) && addr+size > strtonum(t2)) printf "%s contains %s (offset +0x%x)\n", sym, t2, strtonum(t2)-addr
  if (addr <= strtonum(t3) && addr+size > strtonum(t3)) printf "%s contains %s (offset +0x%x)\n", sym, t3, strtonum(t3)-addr
}' 2>/dev/null

